import json
lines = open('ios_crash.ips').readlines()
crash = json.loads(''.join(lines[1:]))

# Look for any fields with exception message details
for key in sorted(crash.keys()):
    if key not in ['threads', 'usedImages', 'lastExceptionBacktrace', 'legacyInfo']:
        val = crash[key]
        if isinstance(val, (str, int, float, bool)):
            if key not in ['uptime', 'procLaunch', 'procRole', 'version', 'userID', 'pid', 'cpuType', 'translated']:
                print(f'{key}: {val}')
        elif isinstance(val, dict) and len(json.dumps(val)) < 500:
            print(f'{key}: {json.dumps(val)}')
        elif isinstance(val, list) and len(json.dumps(val)) < 500:
            print(f'{key}: {json.dumps(val)}')

# Check legacyInfo
if 'legacyInfo' in crash:
    li = crash['legacyInfo']
    print(f'\\nlegacyInfo keys: {list(li.keys()) if isinstance(li, dict) else type(li)}')
    if isinstance(li, dict):
        for k,v in li.items():
            print(f'  {k}: {str(v)[:300]}')
